import type { BankQuestion } from "@/lib/bank";

/** Operating Systems (CS Fundamentals): 97 questions. Append new ones at the end with the next id; never reuse or renumber an id. */
const questions: BankQuestion[] = [
  {"id": "cs-operating-systems-1", "question": "In the standard five-state process model, which transition can NEVER happen directly?", "options": ["Waiting → Running", "Running → Waiting", "Ready → Running", "Waiting → Ready"], "answer": 0, "explanation": "A process whose I/O or event completes moves from Waiting to Ready and must then be picked by the scheduler; it cannot jump straight to Running. The other three transitions are all normal.", "difficulty": "easy", "source": "TCS NQT · Infosys pattern"},
  {"id": "cs-operating-systems-2", "question": "The data structure in which the OS keeps a process's program counter, register contents, state and open-file list is called the:", "options": ["Interrupt vector table", "Process Control Block (PCB)", "Page table", "Inode"], "answer": 1, "explanation": "The PCB (task control block) holds everything needed to resume a process after a context switch. An inode describes a file, not a process.", "difficulty": "easy", "source": "Wipro · Cognizant pattern"},
  {"id":"cs-operating-systems-3","question":"Short jobs stuck waiting behind one long CPU-bound job is called the convoy effect. It is characteristic of which scheduling algorithm?","options":["Round Robin","Shortest Remaining Time First","First Come First Served","Multilevel feedback queue"],"answer":2,"explanation":"FCFS is non-preemptive and ignores burst length, so a long job at the head of the queue holds up every short job behind it.","difficulty":"easy","source":"Accenture · Capgemini pattern"},
  {"id":"cs-operating-systems-4","question":"A system spends most of its time swapping pages in and out and does very little useful work. This condition is called:","options":["Deadlock","Belady's anomaly","Starvation","Thrashing"],"answer":3,"explanation":"Thrashing happens when processes do not have enough frames for their working sets, so page faults dominate and CPU utilisation collapses.","difficulty":"easy","source":"TCS NQT · Infosys pattern"},
  {"id":"cs-operating-systems-5","question":"Which page-replacement algorithm can show Belady's anomaly (more frames giving more page faults)?","options":["FIFO","LRU","LFU implemented as a stack algorithm","Optimal (OPT)"],"answer":0,"explanation":"FIFO is not a stack algorithm, so the set of pages held with n frames is not always a subset of those held with n + 1 frames; that is what allows the anomaly. OPT and LRU are stack algorithms and never show it.","difficulty":"easy","source":"Wipro · Cognizant pattern"},
  {"id": "cs-operating-systems-6", "question": "The disk-scheduling algorithm in which the head sweeps to one end of the disk servicing requests and then reverses direction, like a lift, is:", "options": ["FCFS", "SCAN", "C-SCAN", "SSTF"], "answer": 1, "explanation": "SCAN is the elevator algorithm: it goes all the way to the end in the current direction, then reverses. C-SCAN instead jumps back to the start without servicing on the return.", "difficulty": "easy", "source": "HCL · Tech Mahindra pattern"},
  {"id":"cs-operating-systems-7","question":"Processes: P1 (arrival 0, burst 7), P2 (arrival 2, burst 4), P3 (arrival 4, burst 1), P4 (arrival 5, burst 4) (times in ms). Under FCFS scheduling, what is the average waiting time?","options":["8.75 ms","4.00 ms","4.75 ms","5.25 ms"],"answer":2,"explanation":"Completion: P1 = 7, P2 = 11, P3 = 12, P4 = 16. Waiting = completion − arrival − burst = 0, 5, 7, 7, so the average is 19/4 = 4.75 ms. 8.75 ms is the average turnaround time, not waiting time.","difficulty":"moderate","source":"TCS NQT · Infosys pattern"},
  {"id":"cs-operating-systems-8","question":"Which of the following is NOT one of the four necessary (Coffman) conditions for deadlock?","options":["Mutual exclusion","Circular wait","Hold and wait","Preemption of resources"],"answer":3,"explanation":"The four conditions are mutual exclusion, hold and wait, NO preemption, and circular wait. Allowing preemption actually breaks a deadlock condition.","difficulty":"moderate","source":"Accenture · Capgemini pattern"},
  {"id":"cs-operating-systems-9","question":"How many times is \"hi\" printed? (Assume every fork() succeeds.)\n```c\nint main() {\n    for (int i = 0; i < 3; i++)\n        fork();\n    printf(\"hi\\n\");\n    return 0;\n}\n```","options":["8","7","6","3"],"answer":0,"explanation":"Each fork doubles the number of processes, so after 3 forks there are 2³ = 8 processes and each prints once. 7 is the number of child processes created, not the number of printers.","difficulty":"moderate","source":"TCS NQT · Infosys pattern"},
  {"id":"cs-operating-systems-10","question":"A system has 32-bit logical addresses, a page size of 4 KB and 4-byte page-table entries. What is the size of a single-level page table for one process?","options":["4 KB","4 MB","1 MB","16 MB"],"answer":1,"explanation":"Pages = 2³² / 2¹² = 2²⁰ entries; 2²⁰ × 4 bytes = 4 MB. 1 MB is the entry count (in millions), forgetting the 4-byte entry size.","difficulty":"moderate","source":"Wipro · Cognizant pattern"},
  {"id":"cs-operating-systems-11","question":"Four processes share a pool of identical resource instances, and each process needs at most 3 instances to finish. What is the minimum number of instances that guarantees deadlock can never occur?","options":["10","8","9","12"],"answer":2,"explanation":"Worst case: each process holds 3 − 1 = 2 instances and waits for one more, using 4 × 2 = 8. One extra instance lets some process finish, so 8 + 1 = 9 is the minimum. With 8, all four can be stuck.","difficulty":"moderate","source":"Product-company MCQ pattern"},
  {"id": "cs-operating-systems-12", "question": "A counting semaphore S is initialised to 5. Then 7 wait (P) operations and 3 signal (V) operations are performed on it in some order. What is the final value of S (using the definition where S may go negative)?", "options": ["−2", "2", "15", "1"], "answer": 3, "explanation": "Each P subtracts 1 and each V adds 1: 5 − 7 + 3 = 1. The order affects which processes block on the way, not the final value.", "difficulty": "moderate", "source": "HCL · Tech Mahindra pattern"},
  {"id":"cs-operating-systems-13","question":"A process of size 13,000 bytes is loaded with paging, page size 4,096 bytes. How much internal fragmentation is there in its last page?","options":["3,384 bytes","712 bytes","0 bytes, because paging has no internal fragmentation","1,096 bytes"],"answer":0,"explanation":"It needs ⌈13000/4096⌉ = 4 pages = 16,384 bytes, so 16,384 − 13,000 = 3,384 bytes are wasted in the last page. Paging removes external fragmentation, not internal.","difficulty":"moderate","source":"TCS NQT · Infosys pattern"},
  {"id":"cs-operating-systems-14","question":"Processes: P1 (arrival 0, burst 7), P2 (arrival 2, burst 4), P3 (arrival 4, burst 1), P4 (arrival 5, burst 4) (ms). Using non-preemptive SJF (ties broken by arrival), what is the average turnaround time?","options":["7.00 ms","8.00 ms","4.00 ms","8.75 ms"],"answer":1,"explanation":"P1 runs 0–7 (only process at t = 0). At 7 all have arrived; shortest is P3 (7–8), then P2 (8–12), then P4 (12–16). Turnaround = 7, 10, 4, 11 → 32/4 = 8 ms. 4 ms is average waiting; 7 ms is what preemptive SRTF gives.","difficulty":"moderate","source":"Accenture · Capgemini pattern"},
  {"id": "cs-operating-systems-15", "question": "A child process has terminated, but its parent has not yet called wait() to read its exit status. The child is now a:", "options": ["Daemon process", "Suspended process", "Zombie process", "Orphan process"], "answer": 2, "explanation": "A zombie keeps its PID and an entry in the process table until the parent reaps it with wait(). An orphan is the opposite case: the parent died first and init/systemd adopts the child.", "difficulty": "moderate", "source": "Wipro · Cognizant pattern"},
  {"id": "cs-operating-systems-16", "question": "In a many-to-one thread model (many user-level threads mapped to one kernel thread), what happens when one thread makes a blocking system call?", "options": ["Only that thread blocks; the others keep running", "The call is converted to a non-blocking call by the CPU", "The kernel creates a new kernel thread automatically", "The entire process blocks"], "answer": 3, "explanation": "The kernel sees only one schedulable entity, so a blocking call blocks all threads of that process. One-to-one models (Linux, Windows) avoid this but cost a kernel thread per user thread.", "difficulty": "moderate", "source": "IBM · Deloitte pattern"},
  {"id":"cs-operating-systems-17","question":"Which disadvantage applies to linked file allocation but NOT to indexed allocation?","options":["Direct (random) access to the i-th block requires following i pointers","Files cannot grow after creation","Space is needed to store an index block","External fragmentation"],"answer":0,"explanation":"With linked allocation, reaching block i means walking the chain from the first block, so random access is slow. Neither linked nor indexed allocation suffers external fragmentation, and the index-block overhead belongs to indexed allocation.","difficulty":"moderate","source":"HCL · Tech Mahindra pattern"},
  {"id":"cs-operating-systems-18","question":"A disk has cylinders 0–199 and the head is at cylinder 72. The request queue, in arrival order, is 110, 25, 160, 47, 130, 8, 95, 185. What is the total head movement under FCFS?","options":["641 cylinders","753 cylinders","290 cylinders","818 cylinders"],"answer":1,"explanation":"|72−110| + |110−25| + |25−160| + |160−47| + |47−130| + |130−8| + |8−95| + |95−185| = 38 + 85 + 135 + 113 + 83 + 122 + 87 + 90 = 753.","difficulty":"moderate","source":"Accenture · Capgemini pattern"},
  {"id": "cs-operating-systems-19", "question": "A disk spins at 7,200 RPM. What is its average rotational latency?", "options": ["8.33 ms", "0.14 ms", "4.17 ms", "2.08 ms"], "answer": 2, "explanation": "One rotation = 60/7200 s = 8.33 ms; on average the sector is half a rotation away, so latency = 4.17 ms. 8.33 ms is the full rotation time.", "difficulty": "moderate", "source": "IBM · Deloitte pattern"},
  {"id":"cs-operating-systems-20","question":"Which statement about a page fault is correct?","options":["It is handled entirely by the MMU without involving the OS","It means the process tried to access an illegal address and is always terminated","It occurs when the TLB misses","It occurs when the referenced page is valid but not currently in main memory"],"answer":3,"explanation":"A page fault traps to the OS when the valid page is not resident; the OS loads it and restarts the instruction. A TLB miss is resolved by walking the page table and need not be a page fault; an invalid address is a different trap (segmentation fault).","difficulty":"moderate","source":"TCS NQT · Infosys pattern"},
  {"id":"cs-operating-systems-21","question":"Processes: P1 (arrival 0, burst 7), P2 (arrival 2, burst 4), P3 (arrival 4, burst 1), P4 (arrival 5, burst 4) (ms). Using preemptive SJF (Shortest Remaining Time First), what is the average waiting time?","options":["3.00 ms","4.00 ms","2.50 ms","7.00 ms"],"answer":0,"explanation":"Gantt: P1 0–2, P2 2–4, P3 4–5, P2 5–7, P4 7–11, P1 11–16. Waiting = 9, 1, 0, 2 → 12/4 = 3 ms. 4 ms is the non-preemptive SJF answer; 7 ms is the average turnaround.","difficulty":"hard","source":"Product-company MCQ pattern"},
  {"id":"cs-operating-systems-22","question":"Processes: P1 (arrival 0, burst 7), P2 (arrival 2, burst 4), P3 (arrival 4, burst 1), P4 (arrival 5, burst 4) (ms). Using Round Robin with time quantum 2 ms, what is the average turnaround time? A process arriving at the same instant a quantum expires joins the ready queue before the preempted process.","options":["8.75 ms","9.00 ms","11.00 ms","5.00 ms"],"answer":1,"explanation":"Gantt: P1 0–2, P2 2–4, P1 4–6, P3 6–7, P2 7–9, P4 9–11, P1 11–13, P4 13–15, P1 15–16. Completion 16, 9, 7, 15 → turnaround 16, 7, 3, 10 = 36/4 = 9 ms. 5 ms is the average waiting time.","difficulty":"hard","source":"TCS NQT · Infosys pattern"},
  {"id":"cs-operating-systems-23","question":"Cylinders 0–199, head at 72. Requests: 110, 25, 160, 47, 130, 8, 95, 185. What is the total head movement under SSTF?","options":["264 cylinders","318 cylinders","290 cylinders","329 cylinders"],"answer":2,"explanation":"From 72 the nearest is 95 (23 away; 47 is 25 away), then 110, 130, 160, 185, then back to 47, 25, 8. Movement = (185 − 72) + (185 − 8) = 113 + 177 = 290.","difficulty":"hard","source":"Product-company MCQ pattern"},
  {"id":"cs-operating-systems-24","question":"Reference string: 3, 1, 4, 3, 2, 1, 5, 3, 4, 1, 2, 5, 4. With 3 frames, initially empty, how many page faults does FIFO produce?","options":["9","12","10","11"],"answer":3,"explanation":"Faults on 3, 1, 4 (cold), then 2 (evict 3), 1 is a hit, 5 (evict 1), 3 (evict 4), 4 (evict 2), 1 (evict 5), 2 (evict 3), 5 (evict 4), 4 (evict 1). Only references 3 (4th) and 1 (6th) hit, so 13 − 2 = 11 faults.","difficulty":"hard","source":"Wipro · Cognizant pattern"},
  {"id":"cs-operating-systems-25","question":"A paging system with a single-level page table has a TLB lookup time of 10 ns, a memory access time of 80 ns, and a TLB hit ratio of 85%. The TLB is searched before the page table. What is the effective memory access time?","options":["102 ns","93.5 ns","110 ns","90 ns"],"answer":0,"explanation":"Hit: 10 + 80 = 90 ns. Miss: 10 + 80 (page table) + 80 (data) = 170 ns. EMAT = 0.85 × 90 + 0.15 × 170 = 76.5 + 25.5 = 102 ns. Forgetting the TLB time on a miss gives a wrong lower value.","difficulty":"hard","source":"Product-company MCQ pattern"},
  {"id":"cs-operating-systems-26","question":"Memory access time is 100 ns and servicing a page fault takes 10 ms. If 1 access in 1,000 causes a page fault, the effective access time is about:","options":["10 ms","10.1 μs","1.1 μs","100.1 ns"],"answer":1,"explanation":"EAT = 0.999 × 100 ns + 0.001 × 10,000,000 ns = 99.9 + 10,000 ≈ 10,100 ns ≈ 10.1 μs, a 100-fold slowdown. The common slip is to forget converting 10 ms to 10⁷ ns.","difficulty":"hard","source":"Amazon · Microsoft MCQ pattern"},
  {"id":"cs-operating-systems-27","question":"Five processes P0–P4 and three resource types A, B, C. Allocation: P0 (1,0,1), P1 (2,1,1), P2 (0,1,2), P3 (1,1,0), P4 (0,0,2). Max: P0 (4,2,3), P1 (3,2,2), P2 (2,3,4), P3 (3,1,2), P4 (1,2,3). Available: (1,1,1). Using the Banker's algorithm, which of these is a safe sequence?","options":["P4, P1, P3, P0, P2","P3, P1, P4, P0, P2","P1, P3, P4, P0, P2","P0, P1, P3, P4, P2"],"answer":2,"explanation":"Need = Max − Allocation: P0 (3,2,2), P1 (1,1,1), P2 (2,2,2), P3 (2,0,2), P4 (1,2,1). Only P1 fits in (1,1,1); then Work = (3,2,2) → P3 → (4,3,2) → P4 → (4,3,4) → P0 → (5,3,5) → P2. Starting with P3 or P4 fails because their need exceeds (1,1,1).","difficulty":"hard","source":"Product-company MCQ pattern"},
  {"id":"cs-operating-systems-28","question":"Two processes must run statements S1 (in P1) and S2 (in P2) such that S2 never executes before S1. Using one semaphore `sync`, which is correct?","options":["sync = 1; P1: wait(sync); S1; signal(sync);   P2: S2;","sync = 1; P1: S1; signal(sync);   P2: wait(sync); S2;","sync = 0; P1: wait(sync); S1;   P2: S2; signal(sync);","sync = 0; P1: S1; signal(sync);   P2: wait(sync); S2;"],"answer":3,"explanation":"With sync = 0, P2's wait blocks until P1 has done S1 and signalled. Initialising sync to 1 lets P2 pass wait immediately, so S2 could run first.","difficulty":"hard","source":"HCL · Tech Mahindra pattern"},
  {"id":"cs-operating-systems-29","question":"A system has 32-bit virtual addresses, 4 KB pages and 4-byte page-table entries, and every page table must fit exactly in one page. How should the virtual address be split for a multilevel page table?","options":["Two levels: 10 + 10 + 12","Single level: 20-bit page number + 12-bit offset","Two levels: 8 + 12 + 12","Three levels: 7 + 7 + 6 + 12"],"answer":0,"explanation":"Offset = 12 bits (4 KB). One page holds 4096/4 = 1024 = 2¹⁰ entries, so each level resolves 10 bits; the 20-bit page number needs 20/10 = 2 levels: 10 + 10 + 12.","difficulty":"hard","source":"Product-company MCQ pattern"},
  {"id":"cs-operating-systems-30","question":"A Unix-style inode has 12 direct pointers, 1 single-indirect and 1 double-indirect pointer. The block size is 1 KB and a block pointer is 4 bytes. What is the maximum file size?","options":["12 KB + 1 MB + 1 GB","12 KB + 256 KB + 64 MB","268 KB","12 KB + 256 KB + 256 MB"],"answer":1,"explanation":"One block holds 1024/4 = 256 pointers. Direct: 12 × 1 KB; single-indirect: 256 × 1 KB = 256 KB; double-indirect: 256 × 256 × 1 KB = 64 MB. 268 KB ignores the double-indirect pointer.","difficulty":"hard","source":"IBM · Deloitte pattern"},
  {"id":"cs-operating-systems-31","question":"Memory holes, in order, are 150 KB, 450 KB, 250 KB, 350 KB and 500 KB. Requests arrive in order: 240 KB, 410 KB, 130 KB, 380 KB. Which placement strategy satisfies ALL four requests?","options":["First fit only","Worst fit only","Best fit only","First fit and worst fit"],"answer":2,"explanation":"First fit: 240→450, 410→500, 130→150, then 380 finds no hole ≥ 380 (largest is 350). Worst fit: 240→500, 410→450, 130→350, then 380 fails. Best fit: 240→250, 410→450, 130→150, 380→500, so all fit.","difficulty":"hard","source":"Wipro · Cognizant pattern"},
  {"id":"cs-operating-systems-32","question":"What does this program print? (Assume fork() succeeds; the order of the two lines may vary.)\n```c\nint x = 5;\nint main() {\n    if (fork() == 0) x++;\n    else x--;\n    printf(\"%d \", x);\n    return 0;\n}\n```","options":["5 5","6 6","6 5","6 4"],"answer":3,"explanation":"After fork the child and parent have separate copies of x (copy-on-write). The child increments its copy to 6, the parent decrements its own to 4. Changes in one are not seen by the other, even though x is global.","difficulty":"hard","source":"TCS NQT · Infosys pattern"},
  {"id":"cs-operating-systems-33","question":"A resource-allocation graph contains a cycle. Which conclusion is correct?","options":["If every resource type in the cycle has exactly one instance, there is a deadlock; otherwise there may or may not be one","The system is deadlocked only if every process is in the cycle","There is never a deadlock unless the graph also has a self-loop","The system is always deadlocked"],"answer":0,"explanation":"With single-instance resources a cycle is necessary and sufficient for deadlock. With multiple instances a cycle is only necessary: another instance may be freed by a process outside the cycle.","difficulty":"hard","source":"Accenture · Capgemini pattern"},
  {"id":"cs-operating-systems-34","question":"Reference string (times 1 to 14): 3, 5, 3, 1, 4, 4, 2, 1, 1, 6, 6, 6, 2, 5. With working-set window Δ = 4 references, what is the working set at time 12 (i.e. just after the 12th reference)?","options":["{6}","{1, 6}","{1, 2, 6, 4}","{2, 1, 6}"],"answer":1,"explanation":"The window covers references 9–12: 1, 6, 6, 6. Distinct pages = {1, 6}, so the working-set size is 2. Including reference 13 (page 2) uses the wrong window.","difficulty":"hard","source":"Product-company MCQ pattern"},
  {"id": "cs-operating-systems-35", "question": "Processes: A (arrival 0, burst 5), B (arrival 1, burst 3), C (arrival 2, burst 8), D (arrival 3, burst 6). Priorities: A = 3, B = 1, C = 4, D = 2 (lower number = higher priority). Under PREEMPTIVE priority scheduling, what is the average waiting time?", "options": ["6.00", "5.25", "5.50", "4.75"], "answer": 2, "explanation": "Gantt: A 0–1, B 1–4 (preempts A), D 4–10, A 10–14, C 14–22. Waiting = 9, 0, 12, 1 → 22/4 = 5.5. Note D does not preempt B because B has higher priority. Non-preemptive priority gives 5.25.", "difficulty": "hard", "source": "HCL · Tech Mahindra pattern"},
  {"id":"cs-operating-systems-36","question":"Cylinders 0–199, head at 72 moving towards higher cylinders. Requests: 110, 25, 160, 47, 130, 8, 95, 185. Under C-LOOK, counting the jump back as head movement, what is the total head movement?","options":["290 cylinders","318 cylinders","329 cylinders","373 cylinders"],"answer":2,"explanation":"Service 95, 110, 130, 160, 185 (113 cylinders), jump to 8 (177), then 25, 47 (39). Total = 113 + 177 + 39 = 329. 373 is C-SCAN (going to 199 and 0); 290 is LOOK.","difficulty":"hard","source":"Amazon · Microsoft MCQ pattern"},
  {"id":"cs-operating-systems-37","question":"In the first readers–writers problem (readers get priority: a reader never waits if the resource is already being read), which problem can occur?","options":["Two writers may write simultaneously","Readers can starve","A reader and a writer may access the data together","Writers can starve"],"answer":3,"explanation":"As long as readers keep arriving, readcount never drops to 0 and the writer's wait on the resource semaphore never succeeds. Mutual exclusion is still preserved; only fairness suffers.","difficulty":"hard","source":"IBM · Deloitte pattern"},
  {"id":"cs-operating-systems-38","question":"When is a spinlock (busy-waiting lock) preferable to a blocking lock?","options":["On a multiprocessor when the lock is held for a very short time, shorter than two context switches","On a single-CPU system when the lock is held for a long time","When there are more threads than CPUs and the lock is heavily contended for long periods","Whenever the critical section performs disk I/O"],"answer":0,"explanation":"Spinning avoids the cost of sleeping and waking (two context switches). It is useful only if another CPU will release the lock soon; on a uniprocessor the spinning thread just wastes its quantum because the holder cannot run.","difficulty":"hard","source":"Product-company MCQ pattern"},
  {"id":"cs-operating-systems-39","question":"Modern fork() implementations use copy-on-write. Which statement is correct?","options":["Only the stack is copied; heap and data remain shared","Pages are shared read-only after fork, and a page is duplicated only when either process writes to it","The entire address space is copied immediately, but lazily mapped","Parent and child share all pages forever, so a write by one is seen by the other"],"answer":1,"explanation":"After fork, both page tables point to the same frames marked read-only. The first write causes a protection fault, and the kernel then copies just that page. Semantics stay as if the whole space were copied.","difficulty":"hard","source":"IBM · Deloitte pattern"},
  {"id": "cs-operating-systems-40", "question": "Segment table (base, limit): S0 (1400, 600), S1 (6300, 400), S2 (4300, 300), S3 (3200, 1100). What happens for logical addresses (2, 120) and (1, 450)?", "options": ["(2, 120) → 4180; (1, 450) → trap", "Both cause a trap", "(2, 120) → 4420; (1, 450) → 6750", "(2, 120) → 4420; (1, 450) → trap: offset exceeds limit"], "answer": 3, "explanation": "(2, 120): offset 120 < limit 300, physical = 4300 + 120 = 4420. (1, 450): offset 450 ≥ limit 400, so the hardware traps to the OS (addressing error). Adding base without checking the limit gives the tempting 6750.", "difficulty": "hard", "source": "HCL · Tech Mahindra pattern"},
  {"id":"cs-operating-systems-41","question":"Page size is 1 KB. The page table maps page 0 → frame 3, page 1 → frame 7, page 2 → frame 5, page 3 → frame 2. What physical address corresponds to logical address 2500?","options":["2500","5120","5572","7620"],"answer":2,"explanation":"Page = ⌊2500/1024⌋ = 2, offset = 2500 − 2048 = 452. Page 2 → frame 5, so physical = 5 × 1024 + 452 = 5572. 5120 forgets the offset.","difficulty":"hard","source":"TCS NQT · Infosys pattern"},
  {"id":"cs-operating-systems-42","question":"Which statement about threads of the same process is FALSE?","options":["They share the code section and global data","They share open files","Each has its own program counter and register set","They share the same stack"],"answer":3,"explanation":"Each thread needs its own stack (local variables, return addresses) plus its own PC and registers. Code, data, heap and open files are shared.","difficulty":"hard","source":"Accenture · Capgemini pattern"},
  {"id": "cs-operating-systems-43", "question": "Processes: A (arrival 0, burst 5), B (arrival 1, burst 3), C (arrival 2, burst 8), D (arrival 3, burst 6). Round Robin, quantum 4. A context switch costs 1 time unit and happens whenever the CPU moves to a different process (none at t = 0, none when the same process continues). A process arriving at the same instant a quantum expires joins the ready queue before the preempted process. What is the average turnaround time?", "options": ["18.75", "20.00", "17.00", "15.25"], "answer": 0, "explanation": "A 0–4, cs, B 5–8 (done), cs, C 9–13, cs, D 14–18, cs, A 19–20 (done), cs, C 21–25 (done), cs, D 26–28 (done). Turnaround = A 20, B 7, C 23, D 25 → 75/4 = 18.75. Without overhead the schedule ends at 22 and gives 15.25.", "difficulty": "very-hard", "source": "Product-company MCQ pattern"},
  {"id":"cs-operating-systems-44","question":"Processes: P1 (arrival 0, burst 7), P2 (arrival 2, burst 4), P3 (arrival 4, burst 1), P4 (arrival 5, burst 4) (ms). Round Robin with quantum 3 ms. A process arriving at the same instant a quantum expires joins the ready queue before the preempted process. What is the completion time of P2, and what is the average response time (first run − arrival)?","options":["P2 completes at 9; average response 1.50 ms","P2 completes at 14; average response 2.75 ms","P2 completes at 13; average response 2.75 ms","P2 completes at 14; average response 3.00 ms"],"answer":1,"explanation":"Gantt: P1 0–3, P2 3–6, P1 6–9, P3 9–10, P4 10–13, P2 13–14, P1 14–15, P4 15–16. P3 and P4 arrive during P2's slice and join the queue behind P1, so P2's second turn comes only at 13. Response times 0, 1, 5, 5 → 11/4 = 2.75 ms.","difficulty":"very-hard","source":"Amazon · Microsoft MCQ pattern"},
  {"id": "cs-operating-systems-45", "question": "Processes: A (arrival 0, burst 5), B (arrival 1, burst 3), C (arrival 2, burst 8), D (arrival 3, burst 6). Priorities A = 3, B = 1, C = 4, D = 2 (lower number = higher priority). Compare preemptive and non-preemptive priority scheduling. Which statement is correct?", "options": ["Preemptive gives 4.75 and non-preemptive 5.25", "Preemptive gives the lower average waiting time, 5.25 vs 5.50", "Non-preemptive gives the lower average waiting time, 5.25 vs 5.50", "Both give 5.50"], "answer": 2, "explanation": "Non-preemptive: A 0–5, B 5–8, D 8–14, C 14–22 → waits 0, 4, 12, 5 = 5.25. Preemptive: A 0–1, B 1–4, D 4–10, A 10–14, C 14–22 → waits 9, 0, 12, 1 = 5.5. Preemption helps high-priority jobs but does not always lower the average.", "difficulty": "very-hard", "source": "Product-company MCQ pattern"},
  {"id":"cs-operating-systems-46","question":"Reference string: 3, 1, 4, 3, 2, 1, 5, 3, 4, 1, 2, 5, 4, 3 frames, initially empty. Which statement is correct?","options":["FIFO and LRU both give 11 faults","LRU gives 12 faults and OPT gives 9","FIFO gives 11 faults and LRU gives 12, so LRU is worse here","LRU gives fewer faults than FIFO, as it always does"],"answer":2,"explanation":"FIFO: 11 faults (hits on the 4th and 6th references). LRU: only the 4th reference (3) hits, so 12 faults. OPT gives 7. LRU is usually better than FIFO but not on every string, which is the trap.","difficulty":"very-hard","source":"Product-company MCQ pattern"},
  {"id": "cs-operating-systems-47", "question": "Reference string: 3, 1, 4, 3, 2, 1, 5, 3, 4, 1, 2, 5, 4. With 3 frames, initially empty, how many page faults does the Optimal (OPT) algorithm produce?", "options": ["6", "9", "8", "7"], "answer": 3, "explanation": "Faults: 3, 1, 4 (cold); 3 hit; 2 replaces 4 (used furthest away); 1 hit; 5 replaces 2 (next used at position 11, later than 3 and 1); 3 hit; 4 replaces 3 (not used again); 1 hit; 2 replaces 1; 5 hit; 4 hit. Total 7.", "difficulty": "very-hard", "source": "Amazon · Microsoft MCQ pattern"},
  {"id": "cs-operating-systems-48", "question": "Assertion (A): For FIFO page replacement, increasing the number of frames can increase the number of page faults.\nReason (R): FIFO is a stack algorithm, so the pages in memory with n frames are always a subset of those with n + 1 frames.", "options": ["Both A and R are true, and R explains A", "Both A and R are true, but R does not explain A", "A is true, R is false", "A is false, R is true"], "answer": 2, "explanation": "A is Belady's anomaly and is true. R is false: FIFO is NOT a stack algorithm; the inclusion property holds for LRU and OPT, which is exactly why they never show the anomaly.", "difficulty": "very-hard", "source": "Product-company MCQ pattern"},
  {"id":"cs-operating-systems-49","question":"Five processes P0–P4 and three resource types A, B, C. Allocation: P0 (1,0,1), P1 (2,1,1), P2 (0,1,2), P3 (1,1,0), P4 (0,0,2). Max: P0 (4,2,3), P1 (3,2,2), P2 (2,3,4), P3 (3,1,2), P4 (1,2,3). Available: (1,1,1). P4 now requests (0, 0, 1). What should the Banker's algorithm do?","options":["Make P4 wait, because the resulting state would be unsafe","Grant it, and the safe sequence becomes P4, P1, P3, P0, P2","Grant it, since the request ≤ Need and ≤ Available","Abort P4, because the request exceeds its maximum claim"],"answer":0,"explanation":"The request passes both checks (≤ Need (1,2,1), ≤ Available (1,1,1)). Pretending to grant it: Available = (1,1,0), P4's need = (1,2,0). Now P1 needs (1,1,1), but C = 0, and nobody else fits either, so the state is unsafe and P4 must wait. Passing the two checks is not enough.","difficulty":"very-hard","source":"Product-company MCQ pattern"},
  {"id":"cs-operating-systems-50","question":"A system has 6 identical tape drives. Each of n processes needs at most 2 drives. What is the maximum n for which the system is guaranteed to be deadlock-free?","options":["3","5","4","6"],"answer":1,"explanation":"Deadlock-free if n(2 − 1) + 1 ≤ 6, i.e. n ≤ 5. With 6 processes each could hold 1 drive and wait for a second with none left. Dividing 6 by 2 to get 3 is the common mistake.","difficulty":"very-hard","source":"Product-company MCQ pattern"},
  {"id": "cs-operating-systems-51", "question": "How many of the following statements about deadlock are correct?\n1. Requiring a process to request all its resources at once prevents hold-and-wait but can lower resource utilisation.\n2. Imposing a total order on resource types and requesting them only in increasing order prevents circular wait.\n3. An unsafe state always means the system is deadlocked.\n4. The Banker's algorithm needs each process to declare its maximum demand in advance.", "options": ["Only one", "Only two", "Only three", "All four"], "answer": 2, "explanation": "1, 2 and 4 are correct. 3 is false: an unsafe state only means deadlock is possible; processes may release resources before requesting their maximum, so it may never happen.", "difficulty": "very-hard", "source": "Product-company MCQ pattern"},
  {"id":"cs-operating-systems-52","question":"Semaphores S = 1 and T = 0. Process X runs: wait(S); print('A'); signal(T);  Process Y runs: wait(T); print('B'); signal(S);  Each runs its code in an infinite loop. Which output prefix is possible?","options":["ABBA…","AABB…","ABAB…","BABA…"],"answer":2,"explanation":"Y cannot print until X signals T, and X cannot print again until Y signals S, so prints strictly alternate starting with A: ABAB… Any other pattern needs two consecutive prints by the same process, which the semaphores forbid.","difficulty":"very-hard","source":"Amazon · Microsoft MCQ pattern"},
  {"id": "cs-operating-systems-53", "question": "Two threads each run the loop `for (i = 0; i < 5; i++) count++;` on a shared int count = 0, with no synchronisation. count++ is compiled to load, add, store. What is the MINIMUM possible final value of count?", "options": ["5", "0", "1", "2"], "answer": 3, "explanation": "Interleaving: T1 loads 0; T2 runs 4 full iterations (count = 4); T1 stores 1; T2 loads 1; T1 runs its remaining 4 iterations; T2 stores 2. Final = 2. It cannot be lower: the last store comes from some thread's 5th iteration, whose load happens after that thread's own 4th store, so it reads at least 1 and writes at least 2.", "difficulty": "very-hard", "source": "Amazon · Microsoft MCQ pattern"},
  {"id":"cs-operating-systems-54","question":"How many times is \"x\" printed? (fork() returns 0 in the child and a positive PID in the parent; assume it always succeeds.)\n```c\nint main() {\n    if (fork() && fork())\n        fork();\n    printf(\"x\\n\");\n    return 0;\n}\n```","options":["4","8","3","5"],"answer":0,"explanation":"&& short-circuits: the first child gets 0 and skips the second fork. The parent forks again; that second child gets 0, so the condition is false. Only the original parent enters the if and forks once more. Processes = parent + 3 children = 4.","difficulty":"very-hard","source":"Product-company MCQ pattern"},
  {"id":"cs-operating-systems-55","question":"How many times is \"x\" printed? (Assume every fork() succeeds.)\n```c\nint main() {\n    fork();\n    fork() || fork();\n    printf(\"x\\n\");\n    return 0;\n}\n```","options":["4","6","8","5"],"answer":1,"explanation":"After the first fork there are 2 processes. In each, the parent of `fork() || fork()` sees a non-zero value and skips the second fork; the child sees 0 and forks again. So each of the 2 processes becomes 3, giving 2 × 3 = 6.","difficulty":"very-hard","source":"Product-company MCQ pattern"},
  {"id":"cs-operating-systems-56","question":"How many lines are printed in total? (Assume every fork() succeeds.)\n```c\nint main() {\n    for (int i = 0; i < 3; i++) {\n        if (fork() == 0)\n            printf(\"%d\\n\", i);\n    }\n    return 0;\n}\n```","options":["12","8","7","3"],"answer":2,"explanation":"Only a newly created child prints, once, at the moment it is created, and then continues the loop. Forks: 1 at i = 0, 2 at i = 1, 4 at i = 2, so 7 lines (one 0, two 1s, four 2s). 8 would count the original process, which never prints.","difficulty":"very-hard","source":"Amazon · Microsoft MCQ pattern"},
  {"id":"cs-operating-systems-57","question":"A 64-bit machine uses 48-bit virtual addresses, 4 KB pages and 8-byte page-table entries. Every page table occupies exactly one page. How many levels of paging are needed?","options":["3","5","2","4"],"answer":3,"explanation":"Offset = 12 bits, leaving 36 bits of page number. One page holds 4096/8 = 512 = 2⁹ entries, so each level resolves 9 bits: 36/9 = 4 levels (as on x86-64). Three levels would cover only 27 of the 36 bits.","difficulty":"very-hard","source":"Amazon · Microsoft MCQ pattern"},
  {"id":"cs-operating-systems-58","question":"A system uses two-level paging and a TLB. TLB access = 10 ns, memory access = 100 ns, TLB hit ratio = 90%. The TLB is searched first, and on a miss both page-table levels are read from memory. What is the effective memory access time?","options":["130 ns","140 ns","210 ns","120 ns"],"answer":0,"explanation":"Hit: 10 + 100 = 110 ns. Miss: 10 + 100 + 100 (two table levels) + 100 (data) = 310 ns. EMAT = 0.9 × 110 + 0.1 × 310 = 99 + 31 = 130 ns. Counting only one table access on a miss gives 120 ns.","difficulty":"very-hard","source":"Product-company MCQ pattern"},
  {"id":"cs-operating-systems-59","question":"TLB access = 20 ns, memory access = 100 ns, single-level page table, TLB searched first. What is the minimum TLB hit ratio for the effective access time to be at most 125 ns?","options":["80%","95%","97.5%","90%"],"answer":1,"explanation":"EAT = h(120) + (1 − h)(220) = 220 − 100h ≤ 125, so h ≥ 0.95. Equivalently, the miss penalty is one extra 100 ns access and only 5 ns of it is allowed on average.","difficulty":"very-hard","source":"Product-company MCQ pattern"},
  {"id": "cs-operating-systems-60", "question": "Memory access takes 100 ns and a page fault takes 5 ms to service. For the effective access time to be at most 20% slower than a fault-free access, the page-fault rate must be at most about:", "options": ["1 in 2,500,000", "1 in 2,500", "1 in 250,000", "1 in 25,000"], "answer": 2, "explanation": "EAT = 100 + p(5,000,000 − 100) ≤ 120 ns, so p ≤ 20/4,999,900 ≈ 4 × 10⁻⁶, about 1 fault per 250,000 accesses. Forgetting that 5 ms = 5 × 10⁶ ns gives wrong options by factors of 1000.", "difficulty": "very-hard", "source": "Amazon · Microsoft MCQ pattern"},
  {"id":"cs-operating-systems-61","question":"A machine has 1 GB of physical memory, 4 KB pages, 64-bit virtual addresses and an inverted page table. How many entries does the inverted page table have, and on what does that number depend?","options":["2²⁰ entries, set by the page size alone","2⁵² entries, set by virtual address size","2¹⁸ entries per process","2¹⁸ entries, set by physical memory size"],"answer":3,"explanation":"An inverted table has one entry per physical frame, shared by all processes: 2³⁰/2¹² = 2¹⁸. Its size does not depend on the virtual address space, which is why it suits 64-bit systems.","difficulty":"very-hard","source":"Product-company MCQ pattern"},
  {"id": "cs-operating-systems-62", "question": "How many of the following statements are correct?\n1. Increasing the degree of multiprogramming always increases CPU utilisation.\n2. Thrashing can be reduced by lowering the degree of multiprogramming.\n3. If the sum of working-set sizes exceeds the number of available frames, thrashing is likely.\n4. Under a global replacement policy, one thrashing process can cause others to thrash.", "options": ["Only one", "Only two", "Only three", "All four"], "answer": 2, "explanation": "2, 3 and 4 are correct. 1 is false: past a point, extra processes push the system into thrashing and CPU utilisation falls sharply.", "difficulty": "very-hard", "source": "Product-company MCQ pattern"},
  {"id":"cs-operating-systems-63","question":"Cylinders 0–199, head at 72 currently moving towards cylinder 0. Requests: 110, 25, 160, 47, 130, 8, 95, 185. Under SCAN, what is the total head movement?","options":["257 cylinders","318 cylinders","241 cylinders","290 cylinders"],"answer":0,"explanation":"Down: 47, 25, 8 then on to cylinder 0 (72 cylinders), then up to 95, 110, 130, 160, 185 (185 cylinders). Total = 72 + 185 = 257. Turning at 8 instead of 0 is LOOK and gives 241; 318 is SCAN in the upward direction.","difficulty":"very-hard","source":"Product-company MCQ pattern"},
  {"id":"cs-operating-systems-64","question":"Cylinders 0–199, head at 72 moving towards higher cylinders. Requests: 110, 25, 160, 47, 130, 8, 95, 185. Under C-SCAN, counting the return sweep from 199 to 0 as head movement, what is the total head movement?","options":["318 cylinders","373 cylinders","329 cylinders","374 cylinders"],"answer":1,"explanation":"Up to 199 servicing 95…185: 127. Return 199 → 0: 199. Then 8, 25, 47: 47. Total = 127 + 199 + 47 = 373. C-LOOK (no trip to the ends) gives 329; SCAN gives 318.","difficulty":"very-hard","source":"Amazon · Microsoft MCQ pattern"},
  {"id": "cs-operating-systems-65", "question": "Cylinders 0–199, head at 72 moving towards higher cylinders. Requests: 110, 25, 160, 47, 130, 8, 95, 185. Which two algorithms give the SAME total head movement for this queue?", "options": ["SCAN and LOOK", "SCAN and C-SCAN", "SSTF and LOOK", "SSTF and C-LOOK"], "answer": 2, "explanation": "SSTF goes 95, 110, 130, 160, 185 then 47, 25, 8, which is exactly LOOK's order here: both total 113 + 177 = 290. SCAN = 318 (goes on to 199), C-LOOK = 329, C-SCAN = 373.", "difficulty": "very-hard", "source": "Product-company MCQ pattern"},
  {"id": "cs-operating-systems-66", "question": "Processes: P1 (arrival 0, burst 7), P2 (arrival 2, burst 4), P3 (arrival 4, burst 1), P4 (arrival 5, burst 4) (ms), scheduled by SRTF. Not counting the initial dispatch at t = 0 or the switch away from the last process when it finishes, how many context switches occur?", "options": ["6", "3", "4", "5"], "answer": 3, "explanation": "Gantt: P1 0–2 | P2 2–4 | P3 4–5 | P2 5–7 | P4 7–11 | P1 11–16. Switches at 2, 4, 5, 7 and 11 = 5. P4 arriving at 5 does not preempt P2 (remaining 2 < 4), a common miscount.", "difficulty": "very-hard", "source": "Product-company MCQ pattern"},
  {"id":"cs-operating-systems-67","question":"A disk rotates at 7,200 RPM, has 400 sectors of 512 bytes per track, and an average seek time of 5 ms. What is the average time to read 4 KB stored in consecutive sectors of one track?","options":["9.33 ms","9.17 ms","13.50 ms","5.17 ms"],"answer":0,"explanation":"Rotation = 8.333 ms; average latency = 4.167 ms. 4 KB = 8 sectors, transfer = 8/400 × 8.333 = 0.167 ms. Total = 5 + 4.167 + 0.167 = 9.33 ms. Forgetting the transfer time gives 9.17; using a full rotation as latency gives 13.50.","difficulty":"very-hard","source":"IBM · Deloitte pattern"},
  {"id": "cs-operating-systems-68", "question": "Two processes use this code for mutual exclusion; `turn` is shared and starts at 0. Which property does it FAIL?\n```c\n// Process i (i = 0 or 1)\nwhile (true) {\n    while (turn != i) ;   // busy wait\n    /* critical section */\n    turn = 1 - i;\n    /* remainder section */\n}\n```", "options": ["It satisfies all three requirements", "Both mutual exclusion and bounded waiting", "Mutual exclusion", "Progress"], "answer": 3, "explanation": "Strict alternation guarantees mutual exclusion and bounded waiting, but if process 0 wants to enter twice in a row while process 1 stays in its remainder section, process 0 is blocked by a process not interested in entering. That violates progress. Peterson's algorithm fixes it with flag[].", "difficulty": "very-hard", "source": "Product-company MCQ pattern"},
  {"id":"cs-operating-systems-69","question":"Producer–consumer with semaphores mutex = 1, empty = N, full = 0. The producer is written as:\n```c\nwait(mutex);\nwait(empty);\n/* add item */\nsignal(mutex);\nsignal(full);\n```\nThe consumer is correct (wait(full); wait(mutex); … signal(mutex); signal(empty);). What can go wrong?","options":["Nothing; the order of the two waits does not matter","Deadlock when the buffer is full: the producer holds mutex while blocked on empty, so the consumer can never enter","Two producers can add items at the same time","The consumer can remove from an empty buffer"],"answer":1,"explanation":"If the buffer is full, the producer acquires mutex and then blocks on empty. The consumer passes wait(full) but blocks on wait(mutex), so neither can proceed. The counting semaphore must be waited on before the mutex.","difficulty":"very-hard","source":"Product-company MCQ pattern"},
  {"id":"cs-operating-systems-70","question":"Match each scheduling algorithm with its property:\n(P) Round Robin  (Q) SRTF  (R) Multilevel feedback queue  (S) FCFS\n(1) Moves processes between queues based on observed CPU usage\n(2) Response time depends on the time quantum\n(3) Non-preemptive and prone to the convoy effect\n(4) Preemptive version of SJF; long jobs may starve","options":["P-1, Q-4, R-2, S-3","P-3, Q-4, R-1, S-2","P-2, Q-4, R-1, S-3","P-2, Q-1, R-4, S-3"],"answer":2,"explanation":"RR's responsiveness is set by the quantum; SRTF is preemptive SJF and can starve long jobs; MLFQ demotes CPU-heavy and promotes waiting processes; FCFS is non-preemptive with the convoy effect.","difficulty":"very-hard","source":"Wipro · Cognizant pattern"},
  {"id": "cs-operating-systems-71", "question": "How many of the following statements are correct?\n1. On a context switch, the TLB must be flushed unless its entries carry an address-space identifier (ASID).\n2. A TLB miss always causes a page fault.\n3. Larger pages reduce page-table size but increase internal fragmentation.\n4. Pure demand paging loads every page of a process at start-up so that later references never fault.", "options": ["Only one", "Only two", "Only three", "All four"], "answer": 1, "explanation": "Only 1 and 3 are correct. 2 is false: on a TLB miss the page table is walked, and if the page is resident the TLB is simply refilled. 4 is false: demand paging loads a page only when it is first referenced, so a pure demand-paged process starts with page faults.", "difficulty": "very-hard", "source": "Product-company MCQ pattern"},
  {"id":"cs-operating-systems-72","question":"A 16 GB disk is formatted with 4 KB blocks and a File Allocation Table (FAT) that has one 4-byte entry per block. How large is the FAT, and why does it matter?","options":["16 MB; it must be read from disk for every block of every file","4 MB; it is stored inside each file's first block","64 MB; one entry per byte of the block","16 MB; it is usually cached in memory so following a file's block chain does not need a disk read per block"],"answer":3,"explanation":"Blocks = 16 GB / 4 KB = 4M = 2²²; 2²² × 4 B = 16 MB. FAT is linked allocation with the links pulled into one table, so caching it makes random access a walk through memory rather than through the disk.","difficulty":"very-hard","source":"HCL · Tech Mahindra pattern"},
  {"id": "cs-operating-systems-73", "question": "How many of the following statements about semaphores and mutexes are correct?\n1. A binary semaphore can be used to achieve mutual exclusion.\n2. A mutex can be released only by the thread that acquired it, whereas a semaphore can be signalled by any thread.\n3. A counting semaphore initialised to 3 lets at most 3 threads into the guarded section at once.\n4. wait() and signal() must themselves execute atomically.", "options": ["Only one", "Only two", "Only three", "All four"], "answer": 3, "explanation": "All four hold. Ownership (2) is the key difference that makes a mutex suitable for locking and a semaphore suitable for signalling between threads; atomicity (4) is what makes either work.", "difficulty": "very-hard", "source": "IBM · Deloitte pattern"},
  {"id":"cs-operating-systems-74","question":"Process L (low priority) holds a lock that high-priority process H needs. Medium-priority process M, which does not need the lock, becomes ready and preempts L. What is this situation called, and what fixes it?","options":["Priority inversion; fixed by priority inheritance (L temporarily runs at H's priority)","Deadlock; fixed by the Banker's algorithm","Convoy effect; fixed by Round Robin","Starvation; fixed by aging"],"answer":0,"explanation":"H is effectively blocked by M, a lower-priority process: priority inversion. With priority inheritance, L inherits H's priority while holding the lock, so M cannot preempt it; L releases the lock quickly and H runs.","difficulty":"very-hard","source":"Product-company MCQ pattern"},
  {"id":"cs-operating-systems-75","question":"Consider this loop:\n```c\nfor (int i = 0; i < 2; i++) {\n    fork();\n    printf(\"-\");\n}\n```\nstdout is redirected to a file (fully buffered) and no fflush is called. How many dashes appear in the file?","options":["4","8","3","6"],"answer":1,"explanation":"6 printf calls run in total, but the buffer is copied by fork. At i = 1, the 2 processes each hold \"-\" unflushed and fork, so all 4 final processes hold \"--\" and flush at exit: 4 × 2 = 8. With line-buffered output and a newline it would be 6.","difficulty":"very-hard","source":"Amazon · Microsoft MCQ pattern"},
  {"id":"cs-operating-systems-76","question":"Which CPU scheduling algorithm can make a long process wait indefinitely if short processes keep arriving?","options":["First-Come, First-Served (FCFS)","Round Robin","None — no scheduling algorithm can cause starvation","Shortest Job First (SJF)"],"answer":3,"explanation":"SJF always prefers the shortest job, so a long job can starve while shorter ones keep arriving. FCFS and Round Robin serve every process in turn, so they do not starve anyone.","difficulty":"easy","source":"TCS NQT · Infosys interview pattern"},
  {"id":"cs-operating-systems-77","question":"Which part of the operating system selects which process in the ready queue gets the CPU next?","options":["Short-term (CPU) scheduler","Long-term (job) scheduler","Medium-term scheduler","Loader"],"answer":0,"explanation":"The short-term scheduler picks the next ready process; the dispatcher then performs the actual switch. The long-term scheduler controls admission into memory, and the medium-term scheduler handles swapping.","difficulty":"easy","source":"Wipro · Cognizant technical pattern"},
  {"id":"cs-operating-systems-78","question":"Processes (arrival, burst): P1 (0, 4), P2 (1, 3), P3 (2, 6), P4 (4, 2). What is the average turnaround time under FCFS?","options":["4.25","8","9","7.5"],"answer":1,"explanation":"Completion times: P1 4, P2 7, P3 13, P4 15. Turnaround = completion − arrival: 4, 6, 11, 11, average 32/4 = 8. 4.25 is the average waiting time; 9 forgets to subtract arrival times for P2.","difficulty":"moderate","source":"Accenture · Capgemini technical pattern"},
  {"id":"cs-operating-systems-79","question":"Reference string: 1, 3, 0, 3, 5, 6, 3, 1, 0, 6, 5, 3. With 3 frames, initially empty, how many page faults does FIFO replacement cause?","options":["10","9","11","7"],"answer":2,"explanation":"FIFO hits only on the second reference (3); every later page has just been evicted when it returns: faults at 1, 3, 0, 5, 6, 3, 1, 0, 6, 5, 3 = 11. 7 is the Optimal count for the same string.","difficulty":"moderate","source":"TCS NQT · Infosys interview pattern"},
  {"id":"cs-operating-systems-80","question":"Pure paging (fixed-size pages and frames) can suffer from which kind of fragmentation?","options":["External fragmentation between frames","Both internal and external fragmentation equally","Neither kind","Internal fragmentation, in the last page of a process"],"answer":3,"explanation":"Any free frame can hold any page, so there is no external fragmentation, but a process rarely fills its last page exactly, wasting part of it. Variable-size segmentation is what suffers external fragmentation.","difficulty":"moderate","source":"Product-company interview pattern"},
  {"id":"cs-operating-systems-81","question":"The Banker’s algorithm is used for which strategy of handling deadlocks?","options":["Deadlock avoidance","Deadlock prevention","Deadlock detection and recovery","Ignoring deadlocks (ostrich approach)"],"answer":0,"explanation":"The Banker’s algorithm grants a request only if the resulting state is safe, i.e. it avoids unsafe states using advance knowledge of maximum needs. Prevention instead breaks one of the four Coffman conditions by design.","difficulty":"moderate","source":"Wipro · Cognizant technical pattern"},
  {"id":"cs-operating-systems-82","question":"If the time quantum of Round Robin scheduling is made larger than the longest CPU burst of every process, Round Robin behaves like:","options":["SJF","FCFS","Priority scheduling","Shortest Remaining Time First"],"answer":1,"explanation":"With such a huge quantum, every process finishes its burst before its quantum expires, so processes simply run to completion in arrival order — FCFS. A very small quantum instead causes heavy context-switch overhead.","difficulty":"moderate","source":"Accenture · Capgemini technical pattern"},
  {"id":"cs-operating-systems-83","question":"Processes (arrival, burst): P1 (0, 6), P2 (2, 2), P3 (3, 4), P4 (5, 1). Round Robin with quantum 2 is used; a newly arrived process joins the ready queue before a process whose quantum just expired. What is the average waiting time?","options":["4","3","3.5","6.75"],"answer":2,"explanation":"Gantt: P1 0–2, P2 2–4, P1 4–6, P3 6–8, P4 8–9, P1 9–11, P3 11–13. Completions: P1 11, P2 4, P3 13, P4 9. Waiting = TAT − burst: 5, 0, 6, 3 → 14/4 = 3.5. 6.75 is the average turnaround time.","difficulty":"hard","source":"Product-company interview pattern"},
  {"id":"cs-operating-systems-84","question":"Processes (arrival, burst): P1 (0, 8), P2 (1, 4), P3 (2, 2), P4 (3, 5). What is the average waiting time under preemptive SJF (Shortest Remaining Time First)?","options":["5.75","4","9","4.25"],"answer":3,"explanation":"P1 0–1, P2 1–2 (4 < 7), P3 2–4 (2 < 3), P2 4–7, P4 7–12, P1 12–19. Waiting: P1 11, P2 2, P3 0, P4 4 → 17/4 = 4.25. 9 is the average turnaround time.","difficulty":"hard","source":"TCS NQT · Infosys interview pattern"},
  {"id":"cs-operating-systems-85","question":"Reference string: 5, 2, 5, 8, 2, 3, 5, 9, 8, 2, 3, 5. With 3 frames, initially empty, how many page faults does LRU replacement cause?","options":["10","9","7","8"],"answer":0,"explanation":"Hits occur only at the 3rd reference (5) and 5th (2); after that each page returns just after being the least recently used: faults at 5, 2, 8, 3, 5, 9, 8, 2, 3, 5 = 10. Optimal would need 7.","difficulty":"hard","source":"Wipro · Cognizant technical pattern"},
  {"id":"cs-operating-systems-86","question":"Reference string: 1, 3, 0, 3, 5, 6, 3, 1, 0, 6, 5, 3. With 3 frames, initially empty, how many page faults does the Optimal (Belady’s MIN) algorithm cause?","options":["6","7","8","11"],"answer":1,"explanation":"1, 3, 0 fault (3). At 5 evict 0 (used farthest ahead) → 4. At 6 evict 5 → 5. 3 and 1 hit. At 0 evict 1 (never used again) → 6. 6 hits. At 5 evict 0 or 6 → 7. 3 hits. Total 7; FIFO gives 11.","difficulty":"hard","source":"Accenture · Capgemini technical pattern"},
  {"id":"cs-operating-systems-87","question":"A disk has cylinders 0–199 and the head is at cylinder 100. Pending requests: 45, 130, 12, 180, 90, 150, 60. What is the total head movement under SSTF?","options":["280","348","256","246"],"answer":2,"explanation":"From 100 the nearest is 90 (10), then 60 (30), 45 (15), 12 (33); now 130 is nearest (118), then 150 (20), 180 (30). Total 256. 280 is SCAN towards 0, which travels all the way to cylinder 0 before reversing.","difficulty":"hard","source":"Product-company interview pattern"},
  {"id":"cs-operating-systems-88","question":"Three processes share a single resource type with identical instances. Their maximum needs are 3, 4 and 5 instances. What is the minimum number of instances that guarantees deadlock can never occur?","options":["12","9","13","10"],"answer":3,"explanation":"Worst case: each process holds one less than its maximum, (3 − 1) + (4 − 1) + (5 − 1) = 9, and all are stuck. One more instance lets some process finish and release its holdings, so 9 + 1 = 10. 12 is the total maximum demand, which is more than needed.","difficulty":"hard","source":"TCS NQT · Infosys interview pattern"},
  {"id":"cs-operating-systems-89","question":"Which of the following is NOT a requirement for a correct solution to the critical-section problem?","options":["Processes must enter the critical section in the order they arrive (FIFO)","Mutual exclusion","Progress","Bounded waiting"],"answer":0,"explanation":"The three classical requirements are mutual exclusion, progress (a free critical section cannot be postponed indefinitely), and bounded waiting (a limit on how often others can enter first). Strict FIFO order is stronger than required.","difficulty":"hard","source":"Wipro · Cognizant technical pattern"},
  {"id":"cs-operating-systems-90","question":"Under Highest Response Ratio Next (non-preemptive), the CPU becomes free at time 9. Ready processes (arrival, burst): P2 (2, 3), P3 (4, 6), P4 (6, 2). Which process runs next?","options":["P4","P2","P3","P2 and P4 tie"],"answer":1,"explanation":"Response ratio = (waiting + burst) / burst. P2: (7 + 3)/3 ≈ 3.33; P3: (5 + 6)/6 ≈ 1.83; P4: (3 + 2)/2 = 2.5. P2 has the highest ratio. Pure SJF would pick P4; HRRN boosts jobs that have waited long.","difficulty":"hard","source":"Accenture · Capgemini technical pattern"},
  {"id":"cs-operating-systems-91","question":"Reference string: 6, 1, 6, 2, 0, 1, 6, 4, 2, 1, 0, 4, 6. With 3 frames, initially empty, which set of page-fault counts is correct for FIFO, LRU and Optimal?","options":["FIFO 12, LRU 11, Optimal 8","FIFO 11, LRU 10, Optimal 8","FIFO 11, LRU 12, Optimal 8","FIFO 11, LRU 12, Optimal 7"],"answer":2,"explanation":"Simulating: FIFO faults 11, LRU 12, Optimal 8. LRU is usually better than FIFO, but not on every string — here LRU keeps evicting exactly the page needed next. Only Optimal is guaranteed to be the minimum.","difficulty":"very-hard","source":"Product-company interview pattern"},
  {"id":"cs-operating-systems-92","question":"Disk cylinders 0–199; the head is at cylinder 100 and moving towards cylinder 0. Requests: 45, 130, 12, 180, 90, 150, 60. What is the total head movement under SCAN (elevator), which goes to the end of the disk before reversing?","options":["256","268","378","280"],"answer":3,"explanation":"Moving down: 100 → 90 → 60 → 45 → 12 → 0 = 100 cylinders, then up: 0 → 180 = 180. Total 280. LOOK would turn at 12 instead of 0, giving 256. 378 would be C-SCAN-style jumping that is not SCAN.","difficulty":"very-hard","source":"TCS NQT · Infosys interview pattern"},
  {"id":"cs-operating-systems-93","question":"Working-set window Δ = 4 references. Reference string (times 1 to 10): 1, 2, 1, 3, 4, 4, 3, 5, 1, 2. What is the working set at time 6 (covering references 3 to 6)?","options":["{1, 3, 4}","{1, 2, 3, 4}","{3, 4}","{4, 3, 5}"],"answer":0,"explanation":"References 3–6 are 1, 3, 4, 4, so the distinct pages are {1, 3, 4} (size 3). Including page 2 uses a window of 5; {4, 3, 5} looks at references 6–8 instead.","difficulty":"very-hard","source":"Wipro · Cognizant technical pattern"},
  {"id":"cs-operating-systems-94","question":"In a two-process mutual-exclusion attempt, each process sets its own flag to true and then waits while the other’s flag is true; there is no turn variable (as in Peterson’s algorithm). What can go wrong?","options":["Both may enter the critical section together","Both may set their flags at the same time and then wait for each other forever","One process can enter twice while the other waits forever, but no deadlock is possible","Nothing; flags alone are enough for two processes"],"answer":1,"explanation":"Mutual exclusion holds (a process enters only after seeing the other’s flag false), but if both set their flags before either checks, each waits for the other: deadlock, violating progress. Peterson adds “turn” so one of them always gives way.","difficulty":"very-hard","source":"Accenture · Capgemini technical pattern"},
  {"id":"cs-operating-systems-95","question":"A system runs 4 independent processes, each spending 80% of its time waiting for I/O. Assuming waits are independent, what is the approximate CPU utilisation?","options":["About 80%","About 20%","About 59%","About 41%"],"answer":2,"explanation":"The CPU is idle only when all four processes are waiting at once: 0.8⁴ ≈ 0.41. Utilisation = 1 − 0.8⁴ ≈ 0.59. 41% is the idle fraction; 80% wrongly adds 4 × 20%.","difficulty":"very-hard","source":"Product-company interview pattern"},
  {"id":"cs-operating-systems-96","question":"Processes (arrival, burst, priority — lower number is higher priority): P1 (0, 5, 3), P2 (1, 3, 1), P3 (2, 4, 4), P4 (4, 2, 2). Under preemptive priority scheduling, at what time does P1 complete?","options":["5","8","14","10"],"answer":3,"explanation":"P1 runs 0–1, then P2 (priority 1) preempts and runs 1–4. At 4, P4 (priority 2) beats P1 and runs 4–6. P1 resumes 6–10 with its remaining 4 units. P3 runs last, 10–14. 8 forgets P4’s preemption.","difficulty":"very-hard","source":"TCS NQT · Infosys interview pattern"},
  {"id":"cs-operating-systems-97","question":"int A[256][256] is stored in row-major order, and a page holds 512 ints (two rows). The process has only ONE frame for A, initially empty. How many page faults does this loop cause?\n```c\nfor (j = 0; j < 256; j++)\n    for (i = 0; i < 256; i++)\n        A[i][j] = 0;\n```","options":["32768","128","65536","256"],"answer":0,"explanation":"The loop walks down a column. Rows i and i + 1 (for even i) share a page, so each column touches 128 pages, each faulting because the single frame was holding a different page: 128 × 256 = 32768. A row-wise loop would fault only 128 times; 65536 forgets that two rows share a page.","difficulty":"very-hard","source":"Wipro · Cognizant technical pattern"},
];

export default questions;
